jQuery(document).ready(function(){jQuery("#jform_catid").on("change",function(){var e=jQuery("#jform_catid option:selected").val();jQuery.ajax({url:"index.php?option=com_standard&task=ajax.ajaxProductCategory&id="+e,type:"POST",success:function(e){jQuery("#productcategories").empty().append(e)},error:function(e){console.log(e.message)}}).done(function(e){jQuery("select#jform_catid").removeProp("disabled")})}),jQuery("#jform_catid").trigger("change")});